// Web renk seçici: sayfadaki renk kutusu RGB LED'in rengini PWM ile ayarlar.
#include <WiFi.h>
#include <WebServer.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan
const int KIRMIZI_PIN = 23;
const int YESIL_PIN = 19;
const int MAVI_PIN = 18;
const int PWM_FREKANS = 5000;        // Hz; göz titreme görmez
const int PWM_COZUNURLUK = 8;        // 8 bit: 0-255
const bool ORTAK_ANOT = false;       // ortak anotlu LED'de true yap ve COM'u 3V3'e bağla

WebServer sunucu(80);
int kirmizi = 0, yesil = 0, mavi = 0;

// Renk kutusu değişince sayfa fetch() ile /renk?hex=RRGGBB gönderir.
const char SAYFA[] PROGMEM = R"HTML(<!doctype html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>ESP32 RGB</title>
<style>
body{font-family:sans-serif;text-align:center;padding:20px}
input[type=color]{width:160px;height:160px;border:none;background:none}
#ornek{width:60px;height:60px;border-radius:50%;margin:12px auto;border:2px solid #999;background:#000}
button{font-size:16px;margin:4px;padding:8px 14px;border-radius:8px;border:1px solid #999}
</style></head><body>
<h1>RGB LED rengi</h1>
<input id="renk" type="color" value="#000000">
<div id="ornek"></div>
<p><button onclick="sec('#ff0000')">Kırmızı</button><button onclick="sec('#00ff00')">Yeşil</button>
<button onclick="sec('#0000ff')">Mavi</button><button onclick="sec('#ffffff')">Beyaz</button>
<button onclick="sec('#000000')">Kapat</button></p>
<p id="durum">Bağlanıyor...</p>
<script>
var kutu = document.getElementById('renk');
var mesgul = false, bekleyen = null;
var goster = function (hex) {
  kutu.value = '#' + hex;
  document.getElementById('ornek').style.background = '#' + hex;
  document.getElementById('durum').textContent = 'LED rengi: #' + hex;
};
// ESP32 tek istek işler: istek sürerken gelen son rengi sakla, sonra gönder.
var gonder = function (renk) {
  if (mesgul) { bekleyen = renk; return; }
  mesgul = true;
  fetch('/renk?hex=' + renk.replace('#', '')).then(function (r) { return r.text(); }).then(goster)
    .catch(function () { document.getElementById('durum').textContent = 'ESP32 cevap vermedi.'; })
    .then(function () {
      mesgul = false;
      if (bekleyen) { var b = bekleyen; bekleyen = null; gonder(b); }
    });
};
var sec = function (renk) { kutu.value = renk; gonder(renk); };
kutu.addEventListener('input', function () { gonder(kutu.value); });
fetch('/durum').then(function (r) { return r.text(); }).then(goster);
</script></body></html>)HTML";

void renkYaz() {
  ledcWrite(KIRMIZI_PIN, ORTAK_ANOT ? 255 - kirmizi : kirmizi);
  ledcWrite(YESIL_PIN, ORTAK_ANOT ? 255 - yesil : yesil);
  ledcWrite(MAVI_PIN, ORTAK_ANOT ? 255 - mavi : mavi);
}

String renkMetni() {
  char m[12];
  snprintf(m, sizeof m, "%02x%02x%02x", kirmizi, yesil, mavi);
  return String(m);
}

void anaSayfa() {
  sunucu.send(200, "text/html", SAYFA);
}

// /renk?hex=ff8800 : renk kodunu kırmızı, yeşil, mavi paylarına ayırır.
void renkAyarla() {
  String hex = sunucu.arg("hex");
  if (hex.startsWith("#")) hex = hex.substring(1);
  if (hex.length() != 6) {
    sunucu.send(400, "text/plain", "hex 6 haneli olmali (ornek: ff8800)");
    return;
  }
  long deger = strtol(hex.c_str(), nullptr, 16);
  kirmizi = (deger >> 16) & 0xFF;
  yesil = (deger >> 8) & 0xFF;
  mavi = deger & 0xFF;
  renkYaz();
  Serial.printf("Renk #%s  R=%d G=%d B=%d\n", renkMetni().c_str(), kirmizi, yesil, mavi);
  sunucu.send(200, "text/plain", renkMetni());
}

void durum() {
  sunucu.send(200, "text/plain", renkMetni());
}

void setup() {
  Serial.begin(115200);
  // ESP32 kart paketi 3.x: ledcAttach(pin, frekans, çözünürlük). 2.x'te ledcSetup + ledcAttachPin kullanılır.
  ledcAttach(KIRMIZI_PIN, PWM_FREKANS, PWM_COZUNURLUK);
  ledcAttach(YESIL_PIN, PWM_FREKANS, PWM_COZUNURLUK);
  ledcAttach(MAVI_PIN, PWM_FREKANS, PWM_COZUNURLUK);
  renkYaz();

  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  Serial.print("Wi-Fi'ye baglaniyor");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Baglandi. Tarayicida ac: http://");
  Serial.println(WiFi.localIP());

  sunucu.on("/", anaSayfa);
  sunucu.on("/renk", renkAyarla);
  sunucu.on("/durum", durum);
  sunucu.begin();
}

void loop() {
  sunucu.handleClient();
}
